// demand protocol: the subscriber paces the publisher
SubmissionPublisher<Integer> source = new SubmissionPublisher<>();
source.subscribe(new Flow.Subscriber<Integer>() {
    private Flow.Subscription subscription;
    public void onSubscribe(Flow.Subscription s) {
        subscription = s;
        s.request(16);                 // finite initial demand
    }
    public void onNext(Integer v) {
        process(v);                    // only requested items arrive
        subscription.request(1);       // replenish as work completes
    }
    public void onError(Throwable t) { t.printStackTrace(); }
    public void onComplete() {}
});
// source.submit(value) feeds the subscriber
// thread form: new ArrayBlockingQueue<>(256).put(task) blocks when full

Flux<Event> inbound = source();

inbound.limitRate(256)                         // finite request batches preserve demand
       .onBackpressureBuffer(256, BufferOverflowStrategy.ERROR) // overflow fails explicitly
       .flatMap(e -> process(e), 8)             // at most 8 in-flight calls
       .subscribe();

// shedding instead of waiting (lossy by design):
// inbound.onBackpressureLatest().subscribe(this::render);

var inbound = new ArrayBlockingQueue<Frame>(256);   // the bound

try (var exec = Executors.newVirtualThreadPerTaskExecutor()) {
    for (Frame f : source) {
        inbound.put(f);                             // cheap block on a vthread
        exec.submit(() -> handle(inbound.take()));  // no carrier is pinned
    }
}

